mapper.select:
select r.id, r.user_id, r.dish_id, r.order_id, r.rating, r.content, r.status, r.create_time,
       u.nickname, d.name dishName
from review r
    left join user u on r.user_id = u.id
    left join dish d on r.dish_id = d.id


        r.dish_id = #{dishId}


        and r.user_id = #{userId}


        and r.rating = #{rating}


        and r.status = #{status}


order by r.create_time desc, r.id desc
